<?php

namespace Database\Seeders;

/** Seeds `blog_authors` from database/seeders/data/blog_authors.json (generated by scripts/export-seed-data.ts in the frontend repo). */
class BlogAuthorsSeeder extends ContentSeederBase
{
    public const TABLE = 'blog_authors';

    public function run(): void
    {
        if (! $this->tableReady(self::TABLE)) {
            return;
        }
        $images = ['avatar' => 'blog-authors'];
        $keyCol = $this->hasColumn(self::TABLE, 'slug') ? 'slug' : 'name_ar';

        foreach ($this->json('blog_authors') as $row) {
            if (empty($row[$keyCol])) {
                continue;
            }
            $this->upsertFillEmpty(self::TABLE, [$keyCol => $row[$keyCol]], $row, $images);
        }

        $this->report(self::TABLE);
    }
}
